  endtask

  // Model
  int rd_id_count[16];
  int wr_id_count[16];
  int rd_mid_owner[4];
  int rd_mid_count[4];
  int wr_mid_owner[4];
  int wr_mid_count[4];

  typedef struct {
    logic [SLV_ID_W-1:0] sid;
