  } rtxn_t;
  rtxn_t rd_txns[$];

  typedef struct {
    logic [SLV_ID_W-1:0] sid;
    logic [ADDR_W-1:0] addr;
    logic [7:0] len;
    logic [MST_ID_W-1:0] mid;
    bit mid_valid;
  } wtxn_t;
  wtxn_t wr_txns[$];

  typedef struct {
    logic [ADDR_W-1:0] addr;
    logic [MST_ID_W-1:0] mid;
    logic [7:0] len;
  } m_ar_t;
  m_ar_t m_ar_q[$];

  typedef struct {
    logic [ADDR_W-1:0] addr;
    logic [MST_ID_W-1:0] mid;
    logic [7:0] len;
  } m_aw_t;
  m_aw_t m_aw_q[$];

  typedef struct {
    logic [DATA_W-1:0] data;
    logic [DATA_W/8-1:0] strb;
