  // Monitors

  always @(posedge clk) begin : mon_s_ar
    int distinct;
    if (rst_n && s_arvalid && s_arready) begin
      distinct = 0;
      for (int i = 0; i < 16; i++) if (rd_id_count[i] > 0) distinct++;
      if (rd_id_count[s_arid] >= MAX_TXNS_PER_ID)
        fail("A5", $sformatf("read id=%0d exceeds depth", s_arid));
      if (rd_id_count[s_arid] == 0 && distinct >= MAX_UNIQ_IDS)
        fail("A3", $sformatf("read id=%0d accepted when table full", s_arid));
      rd_id_count[s_arid]++;
      rtxn_t t;
      t.sid = s_arid; t.addr = s_araddr; t.len = s_arlen;
      t.mid = 0; t.mid_valid = 0;
      rd_txns.push_back(t);
    end
  end

  always @(posedge clk) begin : mon_s_aw
    int distinct;
    if (rst_n && s_awvalid && s_awready) begin
      distinct = 0;
      for (int i = 0; i < 16; i++) if (wr_id_count[i] > 0) distinct++;
      if (wr_id_count[s_awid] >= MAX_TXNS_PER_ID)
        fail("A5", $sformatf("write id=%0d exceeds depth", s_awid));
      if (wr_id_count[s_awid] == 0 && distinct >= MAX_UNIQ_IDS)
        fail("A3", $sformatf("write id=%0d accepted when table full", s_awid));
      wr_id_count[s_awid]++;
      wtxn_t t;
      t.sid = s_awid; t.addr = s_awaddr; t.len = s_awlen;
      t.mid = 0; t.mid_valid = 0;
      wr_txns.push_back(t);
    end
  end

  always @(posedge clk) begin : mon_m_ar
    int idx;
    logic [SLV_ID_W-1:0] sid;
    m_ar_t e;
    if (rst_n && m_arvalid && m_arready) begin
      idx = -1;
      for (int i = 0; i < rd_txns.size(); i++) begin
        if (rd_txns[i].addr == m_araddr && !rd_txns[i].mid_valid) begin
          idx = i; break;
        end
      end
      if (idx < 0) begin
        fail("D4", $sformatf("master AR addr=%h has no slave match", m_araddr));
      end else begin
        sid = rd_txns[idx].sid;
        if (rd_txns[idx].len != m_arlen)
          fail("E1", $sformatf("AR len mismatch addr=%h", m_araddr));
        if (rd_mid_count[m_arid] > 0 && rd_mid_owner[m_arid] != sid)
          fail("D1", $sformatf("mid=%0d shared by sid=%0d and sid=%0d",
                               m_arid, rd_mid_owner[m_arid], sid));
        rd_mid_owner[m_arid] = sid;
        rd_mid_count[m_arid]++;
        rd_txns[idx].mid = m_arid;
        rd_txns[idx].mid_valid = 1;
        e.addr = m_araddr; e.mid = m_arid; e.len = m_arlen;
        m_ar_q.push_back(e);
      end
    end
  end

  always @(posedge clk) begin : mon_m_aw
    int idx;
    logic [SLV_ID_W-1:0] sid;
    m_aw_t e;
    if (rst_n && m_awvalid && m_awready) begin
      idx = -1;
      for (int i = 0; i < wr_txns.size(); i++) begin
        if (wr_txns[i].addr == m_awaddr && !wr_txns[i].mid_valid) begin
          idx = i; break;
        end
      end
      if (idx < 0) begin
        fail("D4", $sformatf("master AW addr=%h has no slave match", m_awaddr));
      end else begin
        sid = wr_txns[idx].sid;
        if (wr_txns[idx].len != m_awlen)
          fail("E1", $sformatf("AW len mismatch addr=%h", m_awaddr));
        if (wr_mid_count[m_awid] > 0 && wr_mid_owner[m_awid] != sid)
          fail("D1", $sformatf("mid=%0d shared by sid=%0d and sid=%0d",
                               m_awid, wr_mid_owner[m_awid], sid));
        wr_mid_owner[m_awid] = sid;
        wr_mid_count[m_awid]++;
        wr_txns[idx].mid = m_awid;
        wr_txns[idx].mid_valid = 1;
        e.addr = m_awaddr; e.mid = m_awid; e.len = m_awlen;
        m_aw_q.push_back(e);
      end
    end
  end

  always @(posedge clk) begin : mon_s_w
    exp_w_t e;
    if (rst_n && s_wvalid && s_wready) begin
      e.data = s_wdata; e.strb = s_wstrb; e.last = s_wlast;
      exp_w_q.push_back(e);
    end
  end

  always @(posedge clk) begin : mon_m_w
    exp_w_t e;
    if (rst_n && m_wvalid && m_wready) begin
      if (exp_w_q.size() == 0) begin
        fail("E1", "unexpected master W beat");
      end else begin
        e = exp_w_q.pop_front();
        if (e.data != m_wdata) fail("E1", "W data mismatch");
        if (e.strb != m_wstrb) fail("E1", "W strb mismatch");
        if (e.last != m_wlast) fail("E1", "W last mismatch");
      end
    end
  end

  always @(posedge clk) begin : mon_s_r
    int idx;
    if (rst_n && s_rvalid && s_rready) begin
      idx = -1;
      for (int i = 0; i < exp_r_q.size(); i++) begin
        if (exp_r_q[i].sid == s_rid) begin idx = i; break; end
      end
      if (idx < 0) begin
        fail("C2", $sformatf("unexpected slave R sid=%0d", s_rid));
      end else begin
        if (exp_r_q[idx].data != s_rdata)
          fail("E1", $sformatf("R data mismatch sid=%0d exp=%h got=%h",
                               s_rid, exp_r_q[idx].data, s_rdata));
        if (exp_r_q[idx].last != s_rlast)
          fail("E1", $sformatf("R last mismatch sid=%0d", s_rid));
        exp_r_q.delete(idx);
      end
      idx = -1;
      for (int i = 0; i < rd_txns.size(); i++) begin
        if (rd_txns[i].sid == s_rid) begin idx = i; break; end
      end
      if (idx >= 0) begin
        rd_id_count[s_rid]--;
        if (rd_txns[idx].mid_valid) begin
          rd_mid_count[rd_txns[idx].mid]--;
          if (rd_mid_count[rd_txns[idx].mid] == 0)
            rd_mid_owner[rd_txns[idx].mid] = -1;
        end
        rd_txns.delete(idx);
      end
      s_r_count++;
    end
  end

  always @(posedge clk) begin : mon_s_b
    int idx;
    if (rst_n && s_bvalid && s_bready) begin
      idx = -1;
      for (int i = 0; i < exp_b_q.size(); i++) begin
        if (exp_b_q[i].sid == s_bid) begin idx = i; break; end
      end
      if (idx < 0) begin
        fail("C2", $sformatf("unexpected slave B sid=%0d", s_bid));
      end else begin
        exp_b_q.delete(idx);
      end
      idx = -1;
      for (int i = 0; i < wr_txns.size(); i++) begin
        if (wr_txns[i].sid == s_bid) begin idx = i; break; end
      end
      if (idx >= 0) begin
        wr_id_count[s_bid]--;
        if (wr_txns[idx].mid_valid) begin
          wr_mid_count[wr_txns[idx].mid]--;
          if (wr_mid_count[wr_txns[idx].mid] == 0)
            wr_mid_owner[wr_txns[idx].mid] = -1;
        end
        wr_txns.delete(idx);
      end
      s_b_count++;
    end
  end

  always @(posedge clk) begin : mon_reset
    if (!rst_n) begin
      if (s_rvalid) fail("F1", "s_rvalid high during reset");
      if (s_bvalid) fail("F1", "s_bvalid high during reset");
    end
  end

  always @(negedge rst_n) begin : reset_model
    for (int i = 0; i < 16; i++) begin
      rd_id_count[i] = 0;
      wr_id_count[i] = 0;
    end
    for (int i = 0; i < 4; i++) begin
      rd_mid_owner[i] = -1;
      rd_mid_count[i] = 0;
      wr_mid_owner[i] = -1;
      wr_mid_count[i] = 0;
    end
    rd_txns.delete();
    wr_txns.delete();
    m_ar_q.delete();
    m_aw_q.delete();
    exp_w_q.delete();
    exp_r_q.delete();
    exp_b_q.delete();
  end

  // Helpers
  task automatic wait_m_ar(input logic [ADDR_W-1:0] addr, output logic [MST_ID_W-1:0] mid);
    int timeout = 1000;
    while (timeout > 0) begin
      @(negedge clk);
      for (int i = 0; i < m_ar_q.size(); i++) begin
        if (m_ar_q[i].addr == addr) begin
          mid = m_ar_q[i].mid;
          m_ar_q.delete(i);
          return;
        end
      end
      timeout--;
    end
    fail("D4", $sformatf("timeout waiting for master AR addr=%h", addr));
  endtask

  task automatic wait_m_aw(input logic [ADDR_W-1:0] addr, output logic [MST_ID_W-1:0] mid);
    int timeout = 1000;
    while (timeout > 0) begin
      @(negedge clk);
      for (int i = 0; i < m_aw_q.size(); i++) begin
        if (m_aw_q[i].addr == addr) begin
          mid = m_aw_q[i].mid;
          m_aw_q.delete(i);
          return;
        end
      end
      timeout--;
    end
    fail("D4", $sformatf("timeout waiting for master AW addr=%h", addr));
  endtask

  task automatic wait_exp_r_empty();
    int timeout = 1000;
    while (exp_r_q.size() > 0 && timeout > 0) begin
      @(posedge clk);
      timeout--;
    end
    if (timeout == 0) fail("C2", "timeout waiting for R responses");
  endtask

  task automatic wait_exp_b_empty();
    int timeout = 1000;
    while (exp_b_q.size() > 0 && timeout > 0) begin
      @(posedge clk);
      timeout--;
    end
    if (timeout == 0) fail("C2", "timeout waiting for B responses");
  endtask

  // Tests
  task automatic test_basic_read();
    bit accepted;
    int waited;
    logic [MST_ID_W-1:0] mid;
    exp_r_t e;
    bfm_ar(0, 32'h100, 0, 100, accepted, waited);
    if (!accepted) begin fail("A3", "basic read not accepted"); return; end
    wait_m_ar(32'h100, mid);
    e.sid = 0; e.data = 32'hDEADBEEF; e.last = 1;
    exp_r_q.push_back(e);
    bfm_rbeat(mid, 32'hDEADBEEF, 1);
    wait_exp_r_empty();
  endtask

  task automatic test_basic_write();
    bit accepted;
    int waited;
    logic [MST_ID_W-1:0] mid;
    exp_b_t e;
    bfm_aw(0, 32'h200, 0, 100, accepted, waited);
    if (!accepted) begin fail("A3", "basic write not accepted"); return; end
    bfm_w(32'hCAFEBABE, 4'hF, 1);
    wait_m_aw(32'h200, mid);
    e.sid = 0;
    exp_b_q.push_back(e);
    bfm_bbeat(mid);
    wait_exp_b_empty();
  endtask

  task automatic test_a3_boundary();
    bit accepted;
    int waited;
    logic [MST_ID_W-1:0] mid0, mid1, mid2, mid3, mid4;
    exp_r_t e;
    bfm_ar(0, 32'h1000, 0, 100, accepted, waited);
    if (!accepted) fail("A3", "id=0 not accepted");
    wait_m_ar(32'h1000, mid0);
    bfm_ar(1, 32'h1004, 0, 100, accepted, waited);
    if (!accepted) fail("A3", "id=1 not accepted");
    wait_m_ar(32'h1004, mid1);
    bfm_ar(2, 32'h1008, 0, 100, accepted, waited);
    if (!accepted) fail("A3", "id=2 not accepted");
    wait_m_ar(32'h1008, mid2);
    bfm_ar(3, 32'h100C, 0, 100, accepted, waited);
    if (!accepted) fail("A3", "id=3 not accepted");
    wait_m_ar(32'h100C, mid3);
    bfm_ar(4, 32'h1010, 0, 10, accepted, waited);
    if (accepted) fail("A3", "id=4 accepted when table full");
    e.sid = 0; e.data = 32'hA0; e.last = 1;
    exp_r_q.push_back(e);
    bfm_rbeat(mid0, 32'hA0, 1);
    wait_exp_r_empty();
    bfm_ar(4, 32'h1010, 0, 10, accepted, waited);
    if (!accepted) fail("A4", "id=4 not accepted after retirement");
    if (waited > 2) fail("A4", $sformatf("id=4 accepted after %0d cycles (max 2)", waited));
    wait_m_ar(32'h1010, mid4);
    e.sid = 1; e.data = 32'hA1; e.last = 1; exp_r_q.push_back(e);
    bfm_rbeat(mid1, 32'hA1, 1);
    e.sid = 2; e.data = 32'hA2; e.last = 1; exp_r_q.push_back(e);
    bfm_rbeat(mid2, 32'hA2, 1);
    e.sid = 3; e.data = 32'hA3; e.last = 1; exp_r_q.push_back(e);
    bfm_rbeat(mid3, 32'hA3, 1);
    e.sid = 4; e.data = 32'hA4; e.last = 1; exp_r_q.push_back(e);
    bfm_rbeat(mid4, 32'hA4, 1);
    wait_exp_r_empty();
  endtask

  task automatic test_a5_depth();
    bit accepted;
    int waited;
    logic [MST_ID_W-1:0] mid_a, mid_b, mid_c;
    exp_r_t e;
    bfm_ar(5, 32'h6000, 0, 100, accepted, waited);
    if (!accepted) fail("A5", "id=5 first not accepted");
    wait_m_ar(32'h6000, mid_a);
    bfm_ar(5, 32'h6004, 0, 100, accepted, waited);
    if (!accepted) fail("A5", "id=5 second not accepted");
    wait_m_ar(32'h6004, mid_b);
    bfm_ar(5, 32'h6008, 0, 10, accepted, waited);
    if (accepted) fail("A5", "id=5 third accepted (depth exceeded)");
    e.sid = 5; e.data = 32'hC0; e.last = 1; exp_r_q.push_back(e);
    bfm_rbeat(mid_a, 32'hC0, 1);
    wait_exp_r_empty();
